pub(super) fn generated_dumped_autoload(
    name: &str,
) -> Option<(&'static str, bool, Option<&'static str>)> {
    let index = GENERATED_DUMPED_AUTOLOADS
        .binary_search_by_key(&name, |(candidate, _, _, _)| *candidate)
        .ok()?;
    let (_, file, interactive, kind) = GENERATED_DUMPED_AUTOLOADS[index];
    Some((file, interactive, kind))
}

