pub(super) fn generated_dumped_variable(name: &str) -> Option<&'static str> {
    let index = GENERATED_DUMPED_VARIABLES
        .binary_search_by_key(&name, |(candidate, _)| *candidate)
        .ok()?;
    Some(GENERATED_DUMPED_VARIABLES[index].1)
}
